const syncConnectedButtonSx = {
  height: 40,
  minHeight: 40,
  px: 1.5,
  py: 0,
  borderRadius: 999,
  fontWeight: 600,
  whiteSpace: { xs: 'normal', sm: 'nowrap' },
  transition: 'background-color 0.2s ease, border-color 0.2s ease',
  '&:hover': {
    borderColor: '#2196f3',
    backgroundColor: 'rgba(33, 150, 243, 0.12)',
  },
};

const HIGH_VALUE_BILL_POLL_MS = process.env.NODE_ENV === 'test' ? 0 : 2000;

export type { AccountingConnector };

interface ConnectorApiStatus {
  configured?: boolean;
  enabled?: boolean;
  selfServeConnected?: boolean;
  connectionSource?: string | null;
  syncReady?: boolean;
}

interface MsmeConnectorConnection {
  provider: string;
  connectionType: 'api' | 'import';
  status: string;
  publicMeta?: Record<string, unknown>;
  lastSyncAt?: string | null;
  lastSyncError?: string | null;
}

interface ImportSummary {
  imported: number;
  duplicates: number;
  invalid: number;
  persistFailures: number;
  pendingBillUpload?: number;
}

interface PreviewRow {
  rowIndex: number;
  parsed: {
    description?: string;
    amount?: number;
    date?: string;
    category?: string;
    subcategory?: string;
  };
}

const parseTransactionsFromFile = parseAccountingImportFileClientSide;

const mapTransactionToPending = (txn: Record<string, unknown>): PendingBillUpload => {
  const metadata = (txn.metadata || {}) as Record<string, unknown>;
  const extracted = (metadata.extractedData || {}) as Record<string, unknown>;
  const transactionId = String(txn._id || txn.id || '');
  const sourceId = txn.sourceId != null ? String(txn.sourceId) : undefined;
  return {
    rowIndex: Number(extracted.importRowIndex) || 0,
    transactionId: transactionId || undefined,
    source: txn.source != null ? String(txn.source) : undefined,
    sourceId,
    amount: Number(txn.amount),
    category: txn.category != null ? String(txn.category) : undefined,
    description: txn.description != null ? String(txn.description) : undefined,
    actionRequired: true,
    billStatus: mapHighValueBillStatus(extracted.highValueBillStatus as string | undefined),
    documentId: extracted.billDocumentId != null ? String(extracted.billDocumentId) : undefined,
    uploadRequest: {
      workflow: 'high_value_accounting',
      userGuidance:
        'Upload the matching bill PDF for this pending transaction. Field matching is not proof that the document is authentic.',
      transactionPreview: {
        sourceId,
        amount: Number(txn.amount),
        description: txn.description != null ? String(txn.description) : undefined,
        category: txn.category != null ? String(txn.category) : undefined,
        date: txn.date != null ? String(txn.date) : undefined,
      },
      requiredUpload: {
        requiredPayload: {
          documentType: 'bill',
          sourceWorkflow: 'high_value_accounting',
          linkedSourceId: sourceId,
          linkedTransactionId: transactionId || undefined,
        },
      },
    },
  };
};

const buildDefaultCredentials = (schema: MsmeConnectSchema): Record<string, string | number> => {
  const values: Record<string, string | number> = {};
  schema.fields.forEach((field) => {
    if (field.defaultValue !== undefined) {
      values[field.key] = field.defaultValue;
    } else {
      values[field.key] = field.type === 'number' ? 0 : '';
    }
  });
  return values;
};

const ConnectorBrandAvatar: React.FC<{
  iconStyle: AccountingConnectorIconStyle;
}> = ({ iconStyle }) => {
  const [logoFailed, setLogoFailed] = useState(false);
  const showLogo = Boolean(iconStyle.logoSrc) && !logoFailed;

  return (
    <Avatar
      src={showLogo ? iconStyle.logoSrc : undefined}
      imgProps={{
        onError: () => setLogoFailed(true),
        alt: '',
      }}
      sx={{
        width: 40,
        height: 40,
        bgcolor: iconStyle.backgroundColor,
        color: iconStyle.color,
        border: '1px solid',
        borderColor: 'divider',
        '& img': { objectFit: 'contain', p: 0.5 },
      }}
      aria-hidden
    >
      {iconStyle.icon}
    </Avatar>
  );
};

const AccountingConnectorsPanel: React.FC<{
  onTransactionsUpdated?: () => void;
  /** Connectors lists tools. Activity reviews an uploaded file and its rows. */
  variant?: 'connectors' | 'activity';
}> = ({
  onTransactionsUpdated,
  variant = 'connectors',
}) => {
  const navigate = useNavigate();
  const location = useLocation();
  const fileInputRefs = useRef<Record<string, HTMLInputElement | null>>({});
  const [connectors, setConnectors] = useState<AccountingConnector[]>([]);
  const [apiStatusById, setApiStatusById] = useState<Record<string, ConnectorApiStatus>>({});
  const [connectionsByProvider, setConnectionsByProvider] = useState<Record<string, MsmeConnectorConnection>>({});
  const [loading, setLoading] = useState(true);
  const [loadWarning, setLoadWarning] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [syncingAllForCarbon, setSyncingAllForCarbon] = useState(false);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);
  const [busyProviderId, setBusyProviderId] = useState<string | null>(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewProviderName, setPreviewProviderName] = useState('');
  const [previewRows, setPreviewRows] = useState<PreviewRow[]>([]);
  const [previewSummary, setPreviewSummary] = useState('');
  const [pendingBillUploads, setPendingBillUploads] = useState<PendingBillUpload[]>([]);
  const [lastImportResult, setLastImportResult] = useState<LastAccountingImportResult | null>(null);
  const lastImportResultRef = useRef<LastAccountingImportResult | null>(null);
  lastImportResultRef.current = lastImportResult;
  const [importDetailsOpen, setImportDetailsOpen] = useState(false);
  const [importDetailsMode, setImportDetailsMode] = useState<'summary' | 'rows'>('rows');
  const [importDetailsTab, setImportDetailsTab] = useState<ImportDetailsTab>('imported');
  const [billUploadDialogOpen, setBillUploadDialogOpen] = useState(false);
  const [uploadingSourceId, setUploadingSourceId] = useState<string | null>(null);
  const [connectDialogOpen, setConnectDialogOpen] = useState(false);
  const [connectProviderId, setConnectProviderId] = useState<string | null>(null);
  const [connectSchema, setConnectSchema] = useState<MsmeConnectSchema | null>(null);
  const [connectCredentials, setConnectCredentials] = useState<Record<string, string | number>>({});
  const [clarificationDrafts, setClarificationDrafts] = useState<Record<string, ClarificationDraft>>({});
  const [decisionBatchId, setDecisionBatchId] = useState<string | null>(null);
  const [decidingFile, setDecidingFile] = useState(false);

  const loadConnectors = useCallback(async () => {
    setLoading(true);
    setLoadWarning(null);

    let connectorList: AccountingConnector[] = ACCOUNTING_CONNECTOR_CATALOG;
    let connections: MsmeConnectorConnection[] = [];
    let usedCatalogFallback = true;

    try {
      const [connectorsResponse, connectionsResponse] = await Promise.all([
        ApiService.getAccountingConnectors(),
        ApiService.getMsmeConnectorConnections().catch(() => ({ success: true, data: { connections: [] } })),
      ]);

      const apiConnectors = (connectorsResponse?.data?.connectors ?? []) as AccountingConnector[];
      if (apiConnectors.length > 0) {
        connectorList = apiConnectors;
        usedCatalogFallback = false;
      } else if (connectorsResponse?.success === false) {
        setLoadWarning(
          connectorsResponse?.message || 'Showing offline connector catalog. Live status may be unavailable.'
        );
      }

      connections = (connectionsResponse?.data?.connections ?? []) as MsmeConnectorConnection[];
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unable to reach the connectors API.';
      setLoadWarning(`${message} Showing Tally, Zoho, QuickBooks, and other tools from the local catalog.`);
    }

    setConnectors(connectorList.filter((connector) => !HR_SOFTWARE_CONNECTOR_IDS.has(connector.id)));
    setConnectionsByProvider(
      Object.fromEntries(connections.map((connection) => [connection.provider, connection]))
    );
    setLoading(false);

    if (usedCatalogFallback) {
      setApiStatusById({});
      return;
    }

    try {
      const statusResponse = await ApiService.getAccountingApiStatus();
      const statuses = (statusResponse?.data?.connectors ?? []) as Array<{
        id?: string;
        api?: ConnectorApiStatus;
      }>;
      setApiStatusById(Object.fromEntries(
        statuses
          .filter((status) => status?.id)
          .map((status) => [status.id as string, status.api ?? {}])
      ));
    } catch {
      setApiStatusById({});
    }
  }, []);

  const fetchPendingHighValueTransactions = useCallback(async (): Promise<PendingBillUpload[]> => {
    // limit:200 is the API page size for listing provisional high-value rows —
    // not a default "Bill required" count for Import complete.
    const response = await ApiService.getTransactions({
      page: 1,
      limit: 200,
      highValueBillPending: true,
    });
    const rows = Array.isArray(response?.data?.transactions)
      ? response.data.transactions as Record<string, unknown>[]
      : [];
    return rows.map(mapTransactionToPending);
  }, []);

  /**
   * Update statuses for the current import's pending rows from live data.
   * Does not drop session rows that are not yet visible in the live query (avoids post-import races).
   */
  const enrichSessionPendingFromLive = useCallback(async (session: LastAccountingImportResult) => {
    try {
      const livePending = await fetchPendingHighValueTransactions();
      const enriched = session.pendingBillUpload.map((row) => (
        livePending.find((live) => isSamePendingRow(live, row)) || row
      ));
      setPendingBillUploads(enriched);
      setLastImportResult({
        ...session,
        pendingBillUpload: enriched,
        actionRequired: enriched.length > 0,
        totals: {
          ...session.totals,
          pendingBillUpload: session.totals.pendingBillUpload,
        },
      });
    } catch {
      // Keep this import's pending rows if the durable list request fails.
    }
  }, [fetchPendingHighValueTransactions]);

  /**
   * Reconcile the CURRENT import's bill-required rows with live provisional transactions.
   * Rows missing from live are treated as activated (bill workflow completed).
   * Never fabricates an Import-complete summary from company-wide pending bills.
   */
  const loadPendingHighValueTransactions = useCallback(async (
    session?: LastAccountingImportResult | null
  ) => {
    try {
      const livePending = await fetchPendingHighValueTransactions();
      const base = session !== undefined ? session : lastImportResultRef.current;
      if (!base) {
        // Orphan pending bills remain uploadable; they do not invent an Import-complete card.
        setPendingBillUploads(livePending);
        return;
      }
      const { stillPending, activatedCount } = reconcileImportPendingWithLive(
        base.pendingBillUpload,
        livePending
      );
      const reportedPending = base.totals.pendingBillUpload ?? base.pendingBillUpload.length;
      const previewComplete = base.pendingBillUpload.length >= reportedPending;
      const nextPendingCount = previewComplete
        ? stillPending.length
        : Math.max(0, reportedPending - activatedCount);
      const next: LastAccountingImportResult = {
        ...base,
        actionRequired: nextPendingCount > 0,
        pendingBillUpload: stillPending,
        totals: {
          ...base.totals,
          pendingBillUpload: nextPendingCount,
          imported: base.totals.imported + activatedCount,
        },
      };
      setLastImportResult(next);
      setPendingBillUploads(stillPending);
    } catch {
      // Keep any in-memory pending rows if the list request fails.
    }
  }, [fetchPendingHighValueTransactions]);

  const prepareImportFileReview = useCallback((session: LastAccountingImportResult) => {
    const batchId = session.fileConfirmation?.batchId;
    if (!batchId) return;
    const queue = Array.isArray(session.pendingClarifications) ? session.pendingClarifications : [];
    setDecisionBatchId(batchId);
    setClarificationDrafts((current) => {
      const next: Record<string, ClarificationDraft> = {};
      queue.forEach((row) => {
        next[row.transactionId] = current[row.transactionId] || {
          text: '',
          quantity: row.quantity || '',
          unit: row.unit || row.unitOptions?.[0] || '',
          originAirport: '',
          destinationAirport: '',
          saved: false,
        };
      });
      return next;
    });
  }, []);

  const hydrateLatestImport = useCallback(async () => {
    try {
      const response = await ApiService.getLatestAccountingImport();
      const snapshot = response?.data;
      if (response?.success !== false && snapshot && typeof snapshot === 'object' && (snapshot as { fileName?: string }).fileName) {
        const data = snapshot as Record<string, unknown>;
        const mapped = mapAccountingImportResult({
          data,
          providerId: String(data.providerId || 'unknown'),
          providerLabel: String(data.providerLabel || data.providerId || 'Accounting'),
          fileName: String(data.fileName || 'import'),
          message: typeof data.message === 'string' ? data.message : undefined,
        });
        setLastImportResult(mapped);
        setPendingBillUploads(mapped.pendingBillUpload);
        setImportDetailsTab(resolveInitialImportDetailsTab(mapped));
        if (mapped.carbonAnalysisStatus === 'awaiting_confirmation' && mapped.fileConfirmation?.batchId) {
          prepareImportFileReview(mapped);
        }
        // On reload: drop activated rows, keep only this import's still-pending bills.
        await loadPendingHighValueTransactions(mapped);
        return;
      }
    } catch {
      // Fall through to orphan pending load when latest-import API is unavailable.
    }
    await loadPendingHighValueTransactions(null);
  }, [loadPendingHighValueTransactions, prepareImportFileReview]);

  useEffect(() => {
    void loadConnectors();
    void hydrateLatestImport();
  }, [loadConnectors, hydrateLatestImport]);

  useEffect(() => {
    const carried = (location.state as { accountingImport?: LastAccountingImportResult } | null)?.accountingImport;
    if (variant !== 'activity' || !carried?.fileConfirmation?.batchId) return;
    setLastImportResult(carried);
    setPendingBillUploads(carried.pendingBillUpload || []);
    prepareImportFileReview(carried);
  }, [location.state, prepareImportFileReview, variant]);

  const isConnectorReady = (connectorId: string) => {
    const apiStatus = apiStatusById[connectorId];
    const connection = connectionsByProvider[connectorId];
    return Boolean(
      apiStatus?.syncReady
      || apiStatus?.configured
      || apiStatus?.selfServeConnected
      || (connection && connection.status === 'connected')
    );
  };

  const openConnectDialog = (providerId: string) => {
    if (isLocalhostOnlyConnectProvider(providerId)) {
      setActionError(
        'TallyPrime live connect is only available when the backend runs on the same machine as Tally (localhost). Use Import file instead.',
      );
      return;
    }
    const schema = getMsmeConnectSchema(providerId);
    const existing = connectionsByProvider[providerId];
    const defaults = buildDefaultCredentials(schema);
    const merged = { ...defaults, ...(existing?.publicMeta as Record<string, string | number> | undefined) };

    setConnectProviderId(providerId);
    setConnectSchema(schema);
    setConnectCredentials(merged);
    setConnectDialogOpen(true);
    setActionError(null);
  };

  const closeConnectDialog = () => {
    setConnectDialogOpen(false);
    setConnectProviderId(null);
    setConnectSchema(null);
    setConnectCredentials({});
  };

  // DEEP-BUG-016: required Zoho/API credentials must be filled before Save & test.
  const connectRequiredMissing = useMemo(() => {
    if (!connectSchema || connectSchema.connectionType !== 'api') return false;
    const fields = Array.isArray(connectSchema.fields) ? connectSchema.fields : [];
    return fields.some((field) => {
      if (!field.required) return false;
      const value = connectCredentials[field.key];
      return value == null || String(value).trim() === '';
    });
  }, [connectSchema, connectCredentials]);

  const handleSaveConnection = async () => {
    if (!connectProviderId || !connectSchema) return;
    if (connectRequiredMissing) {
      setActionError('Fill all required connection fields before saving.');
      return;
    }

    setBusyProviderId(connectProviderId);
    setActionError(null);

    try {
      const payload =
        connectSchema.connectionType === 'api'
          ? { connectionType: 'api' as const, credentials: connectCredentials }
          : { connectionType: 'import' as const };

      const response = await ApiService.connectMsmeAccountingProvider(connectProviderId, payload);
      if (response?.success === false) {
        throw new Error(response?.message || 'Connect failed.');
      }

      if (connectSchema.connectionType === 'api') {
        const testResponse = await ApiService.testMsmeAccountingConnection(connectProviderId);
        if (testResponse?.success === false) {
          throw new Error(testResponse?.message || 'Connection test failed.');
        }
        setActionSuccess(testResponse?.message || `${connectSchema.title} connected and verified.`);
      } else {
        setActionSuccess(`${connectSchema.title}: you can import files anytime from this card.`);
      }

      closeConnectDialog();
      await loadConnectors();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Connect failed.');
    } finally {
      setBusyProviderId(null);
    }
  };

  const handleDisconnect = async (providerId: string) => {
    setBusyProviderId(providerId);
    setActionError(null);

    try {
      const response = await ApiService.disconnectMsmeAccountingProvider(providerId);
      if (response?.success === false) {
        throw new Error(response?.message || 'Disconnect failed.');
      }
      setActionSuccess('Connector disconnected.');
      await loadConnectors();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Disconnect failed.');
    } finally {
      setBusyProviderId(null);
    }
  };

  const openImportDetails = (tab?: ImportDetailsTab) => {
    const nextTab = tab || (lastImportResult
      ? resolveInitialImportDetailsTab(lastImportResult)
      : 'imported');
    setImportDetailsMode('rows');
    setImportDetailsTab(nextTab);
    setImportDetailsOpen(true);
  };

  const openImportSummary = () => {
    setImportDetailsMode('summary');
    setImportDetailsOpen(true);
  };

  const importedActivityPath = location.pathname.startsWith('/enterprise/')
    ? '/enterprise/data?section=operational'
    : '/data?section=operational';

  const handleViewAllImportedActivity = () => {
    navigate(importedActivityPath);
  };

  const summarizeImport = (summary?: ImportSummary, pendingCount = 0) => {
    if (!summary) return 'Import completed.';
    const base = `Imported ${summary.imported} transaction(s). Skipped ${summary.duplicates} duplicate(s), ${summary.invalid} invalid row(s), ${summary.persistFailures} persist failure(s).`;
    if (pendingCount > 0) {
      return `${base} ${pendingCount} high-value transaction(s) need bill uploads for emission breakup.`;
    }
    return base;
  };

  const patchPendingRow = (target: PendingBillUpload, patch: Partial<PendingBillUpload>) => {
    const apply = (rows: PendingBillUpload[]) => rows.map((item) => (
      isSamePendingRow(item, target) ? { ...item, ...patch } : item
    ));
    setPendingBillUploads((current) => apply(current));
    setLastImportResult((current) => {
      if (!current) {
        return current;
      }
      return {
        ...current,
        pendingBillUpload: apply(current.pendingBillUpload),
      };
    });
  };

  const handleBillUpload = async (pending: PendingBillUpload, file: File) => {
    if (!isBillUploadEnabled()) {
      setActionError(BILL_UPLOAD_DISABLED_MESSAGE);
      return;
    }
    const sourceId = pending.sourceId || pending.uploadRequest.transactionPreview?.sourceId;
    const transactionId = pending.transactionId
      || pending.uploadRequest.requiredUpload?.requiredPayload?.linkedTransactionId;
    const workflow = pending.uploadRequest.requiredUpload?.requiredPayload?.sourceWorkflow
      || pending.uploadRequest.workflow
      || 'high_value_accounting';
    const rowKey = pendingRowKey({
      transactionId,
      source: pending.source,
      sourceId,
      rowIndex: pending.rowIndex,
    });

    setUploadingSourceId(rowKey);
    setActionError(null);

    try {
      const response = await documentService.uploadDocument(
        file,
        'bill',
        `Bill for high-value transaction ${sourceId || pending.rowIndex}`,
        'company',
        [],
        {
          sourceWorkflow: workflow,
          linkedSourceId: sourceId,
          linkedTransactionId: transactionId,
        }
      );

      if (response?.success === false) {
        throw new Error(response?.message || 'Bill upload failed.');
      }

      const uploadedDocument = response?.document as { id?: string; _id?: string } | undefined;
      const documentId = String(uploadedDocument?.id || uploadedDocument?._id || '');
      patchPendingRow(pending, {
        billStatus: 'processing',
        documentId: documentId || pending.documentId,
        statusMessage: 'Bill uploaded — processing',
      });
      setActionSuccess('Bill uploaded. Matching and verification run after processing. This is not a check that the PDF is authentic.');

      if (documentId) {
        for (let attempt = 0; attempt < 15; attempt += 1) {
          if (HIGH_VALUE_BILL_POLL_MS > 0) {
            await new Promise((resolve) => {
              window.setTimeout(resolve, HIGH_VALUE_BILL_POLL_MS);
            });
          }
          const latest = await documentService.getDocument(documentId, { skipCache: true });
          const doc = latest?.document as {
            status?: string;
            metadata?: { highValueBillMatchStatus?: string };
          } | undefined;
          const matchStatus = doc?.metadata?.highValueBillMatchStatus;
          const docStatus = String(doc?.status || '');
          if (matchStatus === 'mismatch') {
            patchPendingRow(pending, {
              billStatus: 'mismatch',
              statusMessage: 'This bill does not match the selected transaction.',
            });
            setActionError('This bill does not match the selected transaction. The pending transaction was not activated. You can retry with another bill.');
            break;
          }
          if (matchStatus === 'matched' || matchStatus === 'insufficient_data') {
            patchPendingRow(pending, {
              billStatus: matchStatus === 'matched' ? 'matched' : 'needs_verification',
              statusMessage: formatHighValueBillStatus(
                matchStatus === 'matched' ? 'matched' : 'needs_verification'
              ),
            });
            break;
          }
          if (docStatus === 'failed' || docStatus === 'error') {
            patchPendingRow(pending, {
              billStatus: 'failed',
              statusMessage: 'Processing failed. The pending transaction is unchanged.',
            });
            setActionError('Bill processing failed. The pending transaction is unchanged. You can retry.');
            break;
          }
          patchPendingRow(pending, {
            billStatus: 'processing',
            statusMessage: 'Bill uploaded — processing',
          });
        }
        await loadPendingHighValueTransactions();
      }
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Bill upload failed.');
      patchPendingRow(pending, {
        billStatus: pending.billStatus || 'awaiting_bill',
        statusMessage: 'Upload failed. The pending transaction is unchanged.',
      });
    } finally {
      setUploadingSourceId(null);
    }
  };

  const handleImportFile = async (providerId: string, file: File) => {
    setBusyProviderId(providerId);
    setActionError(null);
    setActionSuccess(null);

    try {
      const loweredName = file.name.toLowerCase();
      const useFileUploadEndpoint = loweredName.endsWith('.xml')
        || loweredName.endsWith('.xlsx')
        || loweredName.endsWith('.xls')
        || loweredName.endsWith('.pdf')
        || loweredName.endsWith('.csv');

      const response = useFileUploadEndpoint
        ? await ApiService.importAccountingFile(providerId, file)
        : await (async () => {
          const transactions = await parseTransactionsFromFile(file);
          if (transactions.length === 0) {
            throw new Error('No transactions were found in the selected file.');
          }
          return ApiService.importAccountingTransactions({
            provider: providerId,
            transactions,
            awaitFileConfirmation: true,
            fileName: file.name,
          });
        })();

      if (response?.success === false) {
        throw new Error(response?.message || 'Import failed.');
      }

      const providerLabel = connectors.find((connector) => connector.id === providerId)?.name || providerId;
      const mapped = mapAccountingImportResult({
        data: response?.data,
        providerId,
        providerLabel,
        fileName: file.name,
        message: typeof response?.message === 'string' ? response.message : undefined,
      });
      const pending = mapPendingBillUploads(response?.data?.pendingBillUpload);

      setLastImportResult(mapped);
      setPendingBillUploads(pending);
      setImportDetailsOpen(false);
      setImportDetailsTab(resolveInitialImportDetailsTab(mapped));
      setBillUploadDialogOpen(false);
      if (mapped.carbonAnalysisStatus === 'awaiting_confirmation' && mapped.fileConfirmation?.batchId) {
        prepareImportFileReview(mapped);
        if (variant === 'connectors') {
          navigate(importedActivityPath, { state: { accountingImport: mapped } });
        }
      }
      onTransactionsUpdated?.();
      await enrichSessionPendingFromLive(mapped);
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Import failed.');
    } finally {
      setBusyProviderId(null);
    }
  };

  const handleSyncAllForCarbon = async () => {
    setSyncingAllForCarbon(true);
    setActionError(null);
    setActionSuccess(null);

    try {
      const response = await ApiService.syncAccountingConnectorsForCarbon({
        runAgents: true,
        runOrchestration: true,
        syncAllPages: true,
      });
      if (response?.success === false) {
        throw new Error(response?.message || 'Connector carbon sync failed.');
      }
      const carbonAnalysisStatus = response?.data?.carbonAnalysisStatus as string | undefined;
      const pending = mapPendingBillUploads(response?.data?.pendingBillUpload);
      if (pending.length > 0 || response?.data?.totals) {
        const mapped = mapAccountingImportResult({
          data: response?.data,
          providerId: 'api-sync',
          providerLabel: 'API connectors',
          fileName: 'API sync',
          message: typeof response?.message === 'string' ? response.message : undefined,
        });
        setLastImportResult(mapped);
        setPendingBillUploads(pending);
        await enrichSessionPendingFromLive(mapped);
      }
      setActionSuccess(
        response?.message
        || (carbonAnalysisStatus === 'queued'
          ? 'Import completed. Carbon analysis is continuing in the background.'
          : 'Synced connected APIs and ran multi-agent carbon analysis on imported activity.')
      );
      onTransactionsUpdated?.();
      await loadConnectors();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Connector carbon sync failed.');
    } finally {
      setSyncingAllForCarbon(false);
    }
  };

  const handleSync = async (providerId: string) => {
    setBusyProviderId(providerId);
    setActionError(null);
    setActionSuccess(null);

    try {
      const response = await ApiService.syncAccountingTransactions(providerId, {
        syncAllPages: true,
        runAgents: true,
        runOrchestration: true,
      });
      if (response?.success === false) {
        throw new Error(response?.message || 'Sync failed.');
      }

      const fetchedCount = response?.data?.fetchedCount as number | undefined;
      const summary = summarizeImport(response?.data?.totals as ImportSummary | undefined);
      const orchestrationStatus = (response?.data?.orchestration as { status?: string } | undefined)?.status;
      const carbonAnalysisStatus = response?.data?.carbonAnalysisStatus as string | undefined;
      const carbonTotal = (response?.data?.carbonAssessment as { totalCO2Emissions?: number } | undefined)
        ?.totalCO2Emissions;
      let message = typeof fetchedCount === 'number' ? `${summary} Fetched ${fetchedCount} row(s) from API.` : summary;
      if (typeof carbonTotal === 'number' && carbonTotal > 0) {
        message += ` MSME carbon assessment: ${carbonTotal.toFixed(2)} kg CO₂e.`;
      }
      if (orchestrationStatus === 'completed') {
        message += ' Multi-agent emissions orchestration completed.';
      } else if (carbonAnalysisStatus === 'queued') {
        message += ' Import completed. Carbon analysis is continuing in the background.';
      }
      const pending = mapPendingBillUploads(response?.data?.pendingBillUpload);
      if (pending.length > 0 || response?.data?.totals) {
        const mapped = mapAccountingImportResult({
          data: response?.data,
          providerId,
          providerLabel: connectors.find((connector) => connector.id === providerId)?.name || providerId,
          fileName: 'API sync',
          message: typeof response?.message === 'string' ? response.message : undefined,
        });
        setLastImportResult(mapped);
        setPendingBillUploads(pending);
        setImportDetailsTab(resolveInitialImportDetailsTab(mapped));
        await enrichSessionPendingFromLive(mapped);
      }
      setActionSuccess(message);
      onTransactionsUpdated?.();
      await loadConnectors();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Sync failed.');
    } finally {
      setBusyProviderId(null);
    }
  };

  const handlePreview = async (providerId: string, providerName: string) => {
    setBusyProviderId(providerId);
    setActionError(null);

    try {
      const response = await ApiService.previewAccountingTransactions(providerId, {
        syncAllPages: true,
      });
      if (response?.success === false) {
        throw new Error(response?.message || 'Preview failed.');
      }

      const validRows = (response?.data?.validRows ?? []) as PreviewRow[];
      setPreviewProviderName(providerName);
      setPreviewRows(validRows.slice(0, 10));
      setPreviewSummary(
        `Fetched ${response?.data?.fetchedCount ?? 0}, valid ${response?.data?.validCount ?? 0}, invalid ${response?.data?.invalidCount ?? 0} (showing up to 10 valid rows).`
      );
      setPreviewOpen(true);
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Preview failed.');
    } finally {
      setBusyProviderId(null);
    }
  };

  const confirmImportFile = async (manageBusy = true) => {
    const batchId = decisionBatchId || lastImportResult?.fileConfirmation?.batchId;
    if (!batchId) return;
    if (manageBusy) setDecidingFile(true);
    setActionError(null);
    try {
      const response = await ApiService.confirmAccountingImportFile(batchId);
      if (response?.success === false) {
        throw new Error(response?.message || 'The file was not confirmed.');
      }
      setClarificationDrafts({});
      setLastImportResult((current) => (current ? {
        ...current,
        carbonAnalysisStatus: 'queued',
        message: response?.message || 'Input file confirmed. Carbon analysis is running.',
        fileConfirmation: {
          ...(current.fileConfirmation || {}),
          required: false,
          status: 'confirmed',
        },
      } : current));
      setActionSuccess(response?.message || 'Input file confirmed. Carbon analysis is running.');
      onTransactionsUpdated?.();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'The file was not confirmed.');
    } finally {
      if (manageBusy) setDecidingFile(false);
    }
  };

  const saveImportClarification = async (transactionId: string) => {
    const queue = lastImportResult?.pendingClarifications || [];
    const row = queue.find((item) => item.transactionId === transactionId);
    const draft = clarificationDrafts[transactionId];
    const label = row?.description || row?.title || 'this transaction';
    if (!row || !draft || draft.text.trim().length < 3) {
      setActionError(`Describe what “${label}” is. The voucher description does not say.`);
      return;
    }
    if (!(Number(draft.quantity) > 0) || !draft.unit.trim()) {
      setActionError(`Enter a quantity and unit for “${label}”.`);
      return;
    }
    if (row.requireAirports && (!draft.originAirport.trim() || !draft.destinationAirport.trim())) {
      setActionError(`Enter origin and destination airports for “${label}”.`);
      return;
    }
    setDecidingFile(true);
    setActionError(null);
    try {
      const response = await ApiService.updateTransaction(transactionId, {
        carbonInputBasis: 'activity',
        quantity: Number(draft.quantity),
        unit: draft.unit.trim(),
        transactionClarification: draft.text.trim(),
        clarificationWithoutBill: true,
        originAirport: draft.originAirport.trim() || undefined,
        destinationAirport: draft.destinationAirport.trim() || undefined,
      });
      if (response?.success === false) {
        throw new Error(response?.message || 'Clarification was not saved.');
      }
      const nextDrafts = {
        ...clarificationDrafts,
        [transactionId]: { ...draft, saved: true },
      };
      setClarificationDrafts(nextDrafts);
      const stillOpen = queue.some((item) => item.transactionId && !nextDrafts[item.transactionId]?.saved);
      if (!stillOpen) {
        await confirmImportFile(false);
      } else {
        setActionSuccess('Clarification saved. This row is ready for carbon calculation.');
      }
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'Clarification was not saved.');
    } finally {
      setDecidingFile(false);
    }
  };

  const rejectImportFile = async () => {
    if (!decisionBatchId) return;
    setDecidingFile(true);
    setActionError(null);
    try {
      const response = await ApiService.rejectAccountingImportFile(decisionBatchId);
      if (response?.success === false) {
        throw new Error(response?.message || 'The file was not dropped.');
      }
      setClarificationDrafts({});
      setDecisionBatchId(null);
      setLastImportResult(null);
      setPendingBillUploads([]);
      setActionSuccess(response?.message || 'Input file dropped.');
      onTransactionsUpdated?.();
    } catch (error) {
      setActionError(error instanceof Error ? error.message : 'The file was not dropped.');
    } finally {
      setDecidingFile(false);
    }
  };

  const widelyUsedIds = new Set<string>(WIDELY_USED_MARKET_ERP_IDS);
  const widelyUsedConnectors = WIDELY_USED_MARKET_ERP_IDS
    .map((id) => connectors.find((connector) => connector.id === id))
    .filter((connector): connector is AccountingConnector => Boolean(connector));
  const otherConnectors = connectors.filter((connector) => !widelyUsedIds.has(connector.id));
  const connectorGroups = [
    {
      id: 'widely-used',
      title: 'Widely used',
      intro: 'Connect or import from the accounting tools most businesses use.',
      items: widelyUsedConnectors,
    },
    {
      id: 'other-accounting-tools',
      title: 'Other accounting tools',
      intro: 'More billing and accounting exports.',
      items: otherConnectors,
    },
  ].filter((group) => group.items.length > 0);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress size={32} />
      </Box>
    );
  }

  return (
    <Box sx={{ minWidth: 0, maxWidth: '100%' }}>
      {loadWarning && (
        <Alert
          severity="warning"
          sx={{ mb: 2 }}
          action={(
            <Button color="inherit" size="small" onClick={() => void loadConnectors()}>
              Retry
            </Button>
          )}
        >
          {loadWarning}
        </Alert>
      )}

      {variant === 'connectors' && !lastImportResult && (
        <Box sx={{ mb: 2 }}>
          <Button
            size="small"
            variant="outlined"
            color="success"
            startIcon={syncingAllForCarbon ? <CircularProgress size={14} color="inherit" /> : <AgentIcon sx={{ fontSize: 16 }} />}
            disabled={syncingAllForCarbon || loading}
            onClick={() => void handleSyncAllForCarbon()}
            aria-label="Sync all connected accounting tools"
            sx={syncConnectedButtonSx}
          >
            Sync connected
          </Button>
        </Box>
      )}

      {actionSuccess && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setActionSuccess(null)}>
          {actionSuccess}
        </Alert>
      )}

      {actionError && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setActionError(null)}>
          {actionError}
        </Alert>
      )}

      {variant === 'activity' && lastImportResult?.carbonAnalysisStatus === 'awaiting_confirmation' && lastImportResult.fileConfirmation?.batchId && (
        <ImportFileReview
          result={lastImportResult}
          drafts={clarificationDrafts}
          deciding={decidingFile}
          onDraftChange={(transactionId, patch) => {
            const emptyDraft = {
              text: '',
              quantity: '',
              unit: '',
              originAirport: '',
              destinationAirport: '',
              saved: false,
            };
            setClarificationDrafts((current) => ({
              ...current,
              [transactionId]: {
                ...emptyDraft,
                ...current[transactionId],
                ...patch,
              },
            }));
          }}
          onSaveClarification={(transactionId) => void saveImportClarification(transactionId)}
          onConfirm={() => void confirmImportFile()}
          onCancel={() => void rejectImportFile()}
        />
      )}

      {variant === 'connectors' && lastImportResult?.carbonAnalysisStatus === 'awaiting_confirmation' && (
        <Alert
          severity="info"
          sx={{ mb: 2 }}
          action={(
            <Button color="inherit" size="small" onClick={handleViewAllImportedActivity}>
              Open imported activity
            </Button>
          )}
        >
          This upload is waiting on Imported activity. Amber rows need a clarification before carbon calculation.
        </Alert>
      )}

      {variant === 'connectors' && lastImportResult && (
        <AccountingImportSummary
          result={lastImportResult}
          headerAction={(
            <Button
              size="small"
              variant="outlined"
              color="success"
              startIcon={syncingAllForCarbon ? <CircularProgress size={14} color="inherit" /> : <AgentIcon sx={{ fontSize: 16 }} />}
              disabled={syncingAllForCarbon || loading}
              onClick={() => void handleSyncAllForCarbon()}
              aria-label="Sync all connected accounting tools"
              sx={syncConnectedButtonSx}
            >
              Sync connected
            </Button>
          )}
          onViewImported={() => openImportDetails('imported')}
          onReviewBillRequired={() => {
            if (isBillUploadEnabled()) {
              setBillUploadDialogOpen(true);
            } else {
              openImportDetails('billRequired');
            }
          }}
          onViewImportDetails={() => openImportSummary()}
          onViewAllImportedActivity={handleViewAllImportedActivity}
        />
      )}

      {variant === 'connectors' && !lastImportResult && pendingBillUploads.length > 0 && isBillUploadEnabled() && (
        <Alert
          severity="info"
          sx={{ mb: 2 }}
          action={(
            <Button color="inherit" size="small" onClick={() => setBillUploadDialogOpen(true)}>
              Upload bills
            </Button>
          )}
        >
          {pendingBillUploads.length === 1
            ? '1 saved row can take a bill when you have it.'
            : `${pendingBillUploads.length} saved rows can take a bill when you have it.`}
        </Alert>
      )}

      {variant === 'connectors' && connectorGroups.map((group) => (
      <Box
        key={group.id}
        component="section"
        aria-labelledby={`${group.id}-heading`}
        sx={{ mb: 3 }}
      >
        <Typography id={`${group.id}-heading`} variant="h6" sx={{ fontWeight: 600 }}>
          {group.title}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.25, mb: 1.5 }}>
          {group.intro}
        </Typography>
      <Grid container spacing={2}>
        {group.items.map((connector) => {
          const apiStatus = apiStatusById[connector.id];
          const connection = connectionsByProvider[connector.id];
          const apiReady = isConnectorReady(connector.id);
          const selfServe = Boolean(connection?.status === 'connected' || apiStatus?.selfServeConnected);
          const isBusy = busyProviderId === connector.id;
          const iconStyle = resolveAccountingConnectorIcon(connector.id);

          return (
            <Grid item xs={12} sm={6} lg={4} key={connector.id} sx={{ minWidth: 0 }}>
              <Card
                component="article"
                variant="outlined"
                aria-labelledby={`connector-${connector.id}-name`}
                sx={{ height: '100%', minWidth: 0, maxWidth: '100%', display: 'flex', flexDirection: 'column' }}
              >
                <CardContent sx={{ flexGrow: 1 }}>
                  <Stack direction="row" spacing={1.5} alignItems="flex-start" sx={{ mb: 1 }}>
                    <ConnectorBrandAvatar iconStyle={iconStyle} />
                    <Box sx={{ minWidth: 0, flex: 1 }}>
                      <Typography id={`connector-${connector.id}-name`} variant="subtitle1" sx={{ fontWeight: 600 }}>
                        {connector.name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary" display="block">
                        {connector.vendor}
                      </Typography>
                    </Box>
                  </Stack>
                  <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                    {selfServe && (
                      <Chip size="small" label="Connected" color="success" variant="filled" aria-label={`${connector.name} is connected`} />
                    )}
                    {!selfServe && !isAccountingApiSyncProvider(connector.id) && connector.supportsImport && (
                      <Chip size="small" label="Import" variant="outlined" />
                    )}
                    {!selfServe && isLocalhostOnlyConnectProvider(connector.id) && (
                      <Chip size="small" label="Import" variant="outlined" />
                    )}
                  </Stack>
                  {connection?.lastSyncError && (
                    <Typography variant="caption" color="error" display="block" sx={{ mt: 1 }}>
                      Last sync: {connection.lastSyncError}
                    </Typography>
                  )}
                </CardContent>
                <CardActions sx={{ px: 2, pb: 2, pt: 0, flexWrap: 'wrap', gap: 1 }}>
                  {connector.supportsApiSync && !isLocalhostOnlyConnectProvider(connector.id) && (
                    <>
                      <Button
                        size="small"
                        variant={selfServe ? 'outlined' : 'contained'}
                        startIcon={isBusy ? <CircularProgress size={14} /> : <LinkIcon />}
                        disabled={isBusy}
                        aria-label={selfServe ? `Manage ${connector.name}` : `Connect ${connector.name}`}
                        onClick={() => openConnectDialog(connector.id)}
                        sx={{ minHeight: 40 }}
                      >
                        {selfServe ? 'Manage' : 'Connect'}
                      </Button>
                      {selfServe && (
                        <Button
                          size="small"
                          color="inherit"
                          startIcon={<LinkOffIcon />}
                          disabled={isBusy}
                          aria-label={`Disconnect ${connector.name}`}
                          onClick={() => void handleDisconnect(connector.id)}
                          sx={{ minHeight: 40 }}
                        >
                          Disconnect
                        </Button>
                      )}
                    </>
                  )}
                  <input
                    ref={(element) => {
                      fileInputRefs.current[connector.id] = element;
                    }}
                    type="file"
                    aria-label={`Choose an export file for ${connector.name}`}
                    accept=".json,.csv,.xml,.xlsx,.xls,.pdf,application/json,text/csv,text/xml,application/xml,application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
                    hidden
                    onChange={(event) => {
                      const file = event.target.files?.[0];
                      event.target.value = '';
                      if (file) {
                        void handleImportFile(connector.id, file);
                      }
                    }}
                  />
                  <Button
                    size="small"
                    variant="outlined"
                    startIcon={isBusy ? <CircularProgress size={14} /> : <UploadIcon />}
                    disabled={!connector.supportsImport || isBusy}
                    aria-label={`Import file for ${connector.name}`}
                    onClick={() => fileInputRefs.current[connector.id]?.click()}
                    sx={{ minHeight: 40 }}
                  >
                    Import file
                  </Button>
                  {connector.supportsApiSync && (
                    <>
                      <Button
                        size="small"
                        variant="outlined"
                        startIcon={isBusy ? <CircularProgress size={14} /> : <PreviewIcon />}
                        disabled={!apiReady || isBusy}
                        aria-label={`Preview ${connector.name} API`}
                        onClick={() => void handlePreview(connector.id, connector.name)}
                        sx={{ minHeight: 40 }}
                      >
                        Preview API
                      </Button>
                      <Button
                        size="small"
                        variant="contained"
                        startIcon={isBusy ? <CircularProgress size={14} color="inherit" /> : <SyncIcon />}
                        disabled={!apiReady || isBusy}
                        aria-label={`Sync ${connector.name} now`}
                        onClick={() => void handleSync(connector.id)}
                        sx={{ minHeight: 40 }}
                      >
                        Sync now
                      </Button>
                    </>
                  )}
                </CardActions>
              </Card>
            </Grid>
          );
        })}
      </Grid>
      </Box>
      ))}

      <Dialog open={connectDialogOpen} onClose={closeConnectDialog} maxWidth="sm" fullWidth>
        <DialogTitle>{connectSchema?.title || 'Connect accounting tool'}</DialogTitle>
        <DialogContent dividers>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {connectSchema?.helpText}
          </Typography>
          {connectSchema?.connectionType === 'import' ? (
            <Alert severity="info">
              No API keys needed. After saving, use Import file on this connector card whenever you export data from your
              accounting software.
            </Alert>
          ) : (
            <Stack spacing={2}>
              {connectSchema?.fields.map((field) => {
                if (field.type === 'select') {
                  return (
                    <FormControl key={field.key} fullWidth size="small">
                      <InputLabel>{field.label}</InputLabel>
                      <Select
                        label={field.label}
                        value={String(connectCredentials[field.key] ?? field.defaultValue ?? '')}
                        onChange={(event) => {
                          setConnectCredentials((current) => ({
                            ...current,
                            [field.key]: event.target.value,
                          }));
                        }}
                      >
                        {(field.options || []).map((option) => (
                          <MenuItem key={option} value={option}>
                            {option}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  );
                }

                return (
                  <TextField
                    key={field.key}
                    fullWidth
                    size="small"
                    type={field.type === 'password' ? 'password' : field.type === 'number' ? 'number' : 'text'}
                    label={field.label}
                    required={field.required}
                    placeholder={field.placeholder}
                    value={connectCredentials[field.key] ?? ''}
                    onChange={(event) => {
                      const value = field.type === 'number'
                        ? Number(event.target.value)
                        : event.target.value;
                      setConnectCredentials((current) => ({
                        ...current,
                        [field.key]: value,
                      }));
                    }}
                  />
                );
              })}
            </Stack>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closeConnectDialog}>Cancel</Button>
          <Button
            variant="contained"
            disabled={Boolean(busyProviderId) || connectRequiredMissing}
            onClick={() => void handleSaveConnection()}
          >
            {connectSchema?.connectionType === 'api' ? 'Save & test' : 'Save'}
          </Button>
        </DialogActions>
      </Dialog>

      {lastImportResult && (
        <AccountingImportDetails
          open={importDetailsOpen}
          result={lastImportResult}
          tab={importDetailsTab}
          mode={importDetailsMode}
          uploadingSourceId={uploadingSourceId}
          onClose={() => setImportDetailsOpen(false)}
          onTabChange={(next) => {
            setImportDetailsMode('rows');
            setImportDetailsTab(next);
          }}
          onReviewBillRequired={() => {
            if (isBillUploadEnabled()) {
              setBillUploadDialogOpen(true);
            } else {
              openImportDetails('billRequired');
            }
          }}
          onUploadBill={handleBillUpload}
        />
      )}

      <Dialog
        open={billUploadDialogOpen}
        onClose={() => setBillUploadDialogOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>Upload bills for high-value transactions</DialogTitle>
        <DialogContent dividers>
          {!isBillUploadEnabled() ? (
            <Alert severity="warning" data-testid="bill-upload-disabled" sx={{ mb: 2 }}>
              {BILL_UPLOAD_DISABLED_MESSAGE}
            </Alert>
          ) : null}
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }} data-testid="high-value-bill-basis">
            These high-value transactions are pending supporting bills. A supporting bill is required
            at ₹{HIGH_VALUE_BILL_POLICY.thresholdInr.toLocaleString('en-IN')} or more.
            ₹{HIGH_VALUE_BILL_POLICY.consideredAndNotUsedInr.toLocaleString('en-IN')} is not the control.
            Smaller vouchers still calculate. Upload and verify the matching bill before these rows
            become active. Field matching is not proof that a PDF is authentic.
          </Typography>
          {pendingBillUploads.length === 0 ? (
            <Typography variant="body2">
              No pending high-value transactions need a supporting bill right now.
            </Typography>
          ) : (
            <List dense>
              {pendingBillUploads.map((pending) => {
                const preview = pending.uploadRequest.transactionPreview;
                const rowKey = pendingRowKey(pending);
                const isUploading = uploadingSourceId === rowKey;

                return (
                  <ListItem
                    key={rowKey}
                    alignItems="flex-start"
                    secondaryAction={isBillUploadEnabled() ? (
                      <Button
                        size="small"
                        variant="contained"
                        component="label"
                        disabled={isUploading}
                        startIcon={isUploading ? <CircularProgress size={14} color="inherit" /> : <UploadIcon />}
                      >
                        Upload PDF bill
                        <input
                          hidden
                          type="file"
                          accept="application/pdf,.pdf"
                          onChange={(event) => {
                            const file = event.target.files?.[0];
                            event.target.value = '';
                            if (file) {
                              void handleBillUpload(pending, file);
                            }
                          }}
                        />
                      </Button>
                    ) : undefined}
                  >
                    <ListItemText
                      primary={preview?.description || pending.description || `Row ${pending.rowIndex}`}
                      secondary={`${formatHighValueBillStatus(pending.billStatus)} · ₹${preview?.amount ?? pending.amount ?? 0} · ${preview?.category ?? pending.category ?? 'other'}${pending.statusMessage ? ` · ${pending.statusMessage}` : ''}`}
                    />
                  </ListItem>
                );
              })}
            </List>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setBillUploadDialogOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      <Dialog open={previewOpen} onClose={() => setPreviewOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>API preview — {previewProviderName}</DialogTitle>
        <DialogContent dividers>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {previewSummary}
          </Typography>
          {previewRows.length === 0 ? (
            <Typography variant="body2">No valid rows returned from preview.</Typography>
          ) : (
            <List dense>
              {previewRows.map((row) => (
                <ListItem key={row.rowIndex} alignItems="flex-start">
                  <ListItemText
                    primary={row.parsed.description || 'No description'}
                    secondary={`₹${row.parsed.amount ?? 0} · ${row.parsed.date ?? '—'} · ${row.parsed.category ?? 'other'}/${row.parsed.subcategory ?? '—'}`}
                  />
                </ListItem>
              ))}
            </List>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setPreviewOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default AccountingConnectorsPanel;
