import React from 'react';
import {
  Box,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import type { Document } from '../services/documentService';
import {
  formatBillAmount,
  getBillTransactionPreview,
  getBillTransactionTotal,
} from '../utils/extractedDataVerification';

export interface ExtractedBillTransactionsPreviewProps {
  document: Document;
  compact?: boolean;
}

const ExtractedBillTransactionsPreview: React.FC<ExtractedBillTransactionsPreviewProps> = ({
  document,
  compact = false,
}) => {
  const transactions = getBillTransactionPreview(document);
  const totalAmount = getBillTransactionTotal(transactions);

  if (transactions.length === 0) {
    return (
      <Box sx={{ mt: compact ? 1.5 : 2 }}>
        <Typography variant={compact ? 'subtitle2' : 'subtitle1'} sx={{ fontWeight: 600, mb: 0.5 }}>
          Bill transactions
        </Typography>
        <Typography variant="body2" color="text.secondary">
          No transaction amounts were extracted from this bill yet.
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ mt: compact ? 1.5 : 2 }}>
      <Typography variant={compact ? 'subtitle2' : 'subtitle1'} sx={{ fontWeight: 600, mb: 0.5 }}>
        Bill transactions
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        Review the amounts extracted from your bill. These are read-only. Unverified bills already feed
        provisional inventory and carbon calculations; confirming the fields above upgrades them to confirmed inventory.
      </Typography>

      <TableContainer
        sx={{
          border: '1px solid',
          borderColor: 'divider',
          borderRadius: 1,
          bgcolor: 'background.paper',
          overflowX: 'auto',
          overflowY: 'hidden',
          maxWidth: '100%',
        }}
      >
        <Table size="small" aria-label="Extracted bill transactions" sx={{ width: '100%', minWidth: 360, tableLayout: 'fixed' }}>
          <TableHead>
            <TableRow>
              <TableCell>Description</TableCell>
              <TableCell align="right" sx={{ width: 140, whiteSpace: 'nowrap' }}>
                Amount
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {transactions.map((transaction) => (
              <TableRow key={transaction.id}>
                <TableCell sx={{ whiteSpace: 'normal', overflowWrap: 'break-word', wordBreak: 'normal' }}>
                  <Typography variant="body2" sx={{ whiteSpace: 'normal', overflowWrap: 'break-word' }}>{transaction.description}</Typography>
                </TableCell>
                <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>
                  <Typography variant="body2" sx={{ fontWeight: 500, fontVariantNumeric: 'tabular-nums' }}>
                    {formatBillAmount(transaction.amount)}
                  </Typography>
                </TableCell>
              </TableRow>
            ))}
            <TableRow
              sx={{
                bgcolor: (theme) => (theme.palette.mode === 'dark'
                  ? 'rgba(255, 255, 255, 0.04)'
                  : 'rgba(15, 23, 42, 0.04)'),
                '& td': {
                  borderTop: '2px solid',
                  borderTopColor: 'divider',
                },
              }}
            >
              <TableCell sx={{ whiteSpace: 'normal' }}>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  Total
                </Typography>
              </TableCell>
              <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>
                <Typography variant="body2" sx={{ fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>
                  {formatBillAmount(totalAmount)}
                </Typography>
              </TableCell>
            </TableRow>
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default ExtractedBillTransactionsPreview;
