import { ACCOUNTING_CONNECTOR_CATALOG, type AccountingConnector } from './accountingConnectorCatalog';

/**
 * ERP systems in Data connectors that are widely used by businesses.
 * Order follows how commonly MSMEs and mid-market companies run them.
 * Niche accounting tools in the same catalog stay available as import cards.
 */
export const WIDELY_USED_MARKET_ERP_IDS = [
  'tally',
  'busy',
  'marg',
  'zoho',
  'vyapar',
  'mybillbook',
  'quickbooks',
  'erpnext',
  'odoo',
] as const;

const byId = new Map(ACCOUNTING_CONNECTOR_CATALOG.map((connector) => [connector.id, connector]));

const connectorsFor = (ids: readonly string[]): AccountingConnector[] =>
  ids.map((id) => {
    const connector = byId.get(id);
    if (!connector) {
      throw new Error(`Widely used connector ${id} is missing from the catalog`);
    }
    return connector;
  });

export const WIDELY_USED_MARKET_ERPS = connectorsFor(WIDELY_USED_MARKET_ERP_IDS);

/** HR products are not listed on the Data connectors page. */
export const HR_SOFTWARE_CONNECTOR_IDS = new Set([
  'greythr',
  'darwinbox',
  'sap_successfactors',
]);
