type DuplicateDetectionLike = {
  duplicateType?: string | null;
  decisionTier?: string | null;
} | null | undefined;

/** Customer-facing duplicate copy (display only — no technical tiers/reasons). */
export const CUSTOMER_DUPLICATE_ALERT_TITLE = 'Duplicate Document Found';

export const CUSTOMER_DUPLICATE_ALERT_MESSAGE =
  'This document has already been processed in the system. Please upload a different bill to continue.';

export const CUSTOMER_DUPLICATES_TAB_DESCRIPTION =
  'These uploads match a bill already in your account and were not processed again.';

/**
 * Internal technical tier label — do not use in customer-facing UI.
 */
export function formatDuplicateTierLabel(duplicateDetection?: DuplicateDetectionLike): string {
  const tier = duplicateDetection?.decisionTier || duplicateDetection?.duplicateType;
  switch (tier) {
    case 'file_hash':
      return 'File hash match';
    case 'business_key':
      return 'Business key match';
    case 'gstin_identity':
      return 'GSTIN identity match';
    case 'exact':
      return 'Exact match (legacy)';
    case 'near':
      return 'Near match (legacy)';
    case 'fuzzy':
      return 'Fuzzy match (legacy)';
    default:
      return tier ? String(tier) : 'Duplicate';
  }
}
