import { useCallback, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';

export type UseUrlTabParamOptions = {
  /** When set, out-of-range tab indices fall back to defaultTab (DEEP-BUG-013). */
  maxTab?: number;
};

/**
 * Keeps in-page tab state in sync with the `?tab=` query param for sidebar deep links.
 */
export function useUrlTabParam(
  defaultTab = 0,
  options: UseUrlTabParamOptions = {}
): [number, (value: number) => void] {
  const [searchParams, setSearchParams] = useSearchParams();
  const { maxTab } = options;

  const tab = useMemo(() => {
    const raw = searchParams.get('tab');
    if (raw === null || raw === '') {
      return defaultTab;
    }
    const parsed = Number(raw);
    if (!Number.isFinite(parsed)) {
      return defaultTab;
    }
    if (typeof maxTab === 'number' && maxTab >= 0) {
      // Unknown/out-of-range deep links fall back to the default tab (DEEP-BUG-013),
      // not the last tab — clamping to maxTab previously selected History for ?tab=99.
      if (parsed < 0 || parsed > maxTab) return defaultTab;
    }
    return parsed;
  }, [searchParams, defaultTab, maxTab]);

  const setTab = useCallback(
    (value: number) => {
      setSearchParams(
        (prev) => {
          const next = new URLSearchParams(prev);
          next.delete('section');
          if (value <= 0) {
            next.delete('tab');
          } else {
            next.set('tab', String(value));
          }
          return next;
        },
        { replace: true }
      );
    },
    [setSearchParams]
  );

  return [tab, setTab];
}
